  [("equilibrio", "mantener el cuerpo firme sobre una base pequeña sin caerme"), ("pivotar", "girar sobre las puntas de los pies sin cambiar de lugar"), ("punto fijo", "una marca al frente que miro para no perder el equilibrio"), ("base de apoyo", "la parte del cuerpo que toca el suelo"), ("control", "hacer el movimiento justo donde quiero y detenerme cuando quiero")],
