  [("Explicar un ajuste", "Fallaste varias veces hacia la derecha, giraste más el pie de apoyo y fallaste menos. ¿Qué parte de la explicación es el ajuste?", ["Observé: fallo hacia la derecha.", "Cambié: giro el pie de apoyo.", "Resultado: fallo menos. El ajuste es lo que cambié."], "Girar más el pie de apoyo"),
   ("Medir el esfuerzo", "Al terminar la carrera solo puedes decir una palabra por vez. ¿El esfuerzo fue moderado o muy alto?", ["Si puedo hablar, es moderado.", "Si solo digo una o dos palabras, es muy alto."], "Muy alto")],
  [("Decir «me salió mal» sin explicar nada.", "No sabes qué cambiar ni qué funciona.", "Describe qué observaste, qué cambiaste y qué pasó."), ("Seguir con el mismo esfuerzo aunque te sientas mareado.", "Puedes lesionarte o desmayarte.", "Detente, baja el ritmo, toma agua y avisa a una persona adulta.")],
